// Coronal section previews, generated by scripts/build_index.py.
//
// Zarr chunks are 3D, so reading one plane in the browser means downloading
// every chunk it crosses (hundreds of MB for single-resolution atlases). The
// index builder reads each plane once and stores it here as a small JSON file:
// a contrast-scaled uint8 template plane and the uint32 annotation labels,
// both zlib-compressed, oriented for display (superior at the top).

async function inflate(b64) {
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

/**
 * Load a preview and render it with the atlas colours.
 * @param {string} url  preview JSON
 * @param {Map<number, number[]>} colours  annotation value -> [r, g, b]
 */
export async function loadPreview(url, colours) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  const p = await r.json();
  const n = p.width * p.height;
  const grey = await inflate(p.template);
  const labels = p.labels ? new Uint32Array((await inflate(p.labels)).buffer, 0, n) : null;

  const template = new ImageData(p.width, p.height);
  const overlay = new ImageData(p.width, p.height);
  let last = -1;
  let rgb = null;
  for (let i = 0; i < n; i++) {
    const g = grey[i];
    const o = i * 4;
    template.data[o] = template.data[o + 1] = template.data[o + 2] = g;
    template.data[o + 3] = 255;
    const v = labels ? labels[i] : 0;
    if (v) {
      if (v !== last) {
        rgb = colours.get(v) || [200, 200, 200];
        last = v;
      }
      // region colour over the template
      overlay.data[o] = rgb[0] * 0.8 + g * 0.2;
      overlay.data[o + 1] = rgb[1] * 0.8 + g * 0.2;
      overlay.data[o + 2] = rgb[2] * 0.8 + g * 0.2;
    } else {
      overlay.data[o] = overlay.data[o + 1] = overlay.data[o + 2] = g * 0.5;
    }
    overlay.data[o + 3] = 255;
  }
  return { ...p, template, overlay, labels };
}
